node -e '
const exp = require("./tests/expected.json");
let v = exp.input;
// corrected templates; i = stage number (1-based)
function T1(v){return (v + Math.floor(v/3)) % 997;}
function T2(v,i){return v ^ ((i*7)%64);}
function T3(v,i){return (v*3 - i) % 991;}
function T4(v){return (v*2 + 1) % 1000;}
const fns = [];
for(let s=1;s<=32;s++){
  const m=s%4; // 1->T1,2->T2,3->T3,0->T4
  if(m===1) fns.push(v=>T1(v));
  else if(m===2) fns.push(v=>T2(v,s));
  else if(m===3) fns.push(v=>T3(v,s));
  else fns.push(v=>T4(v));
}
let allok=true;
for(let s=1;s<=32;s++){
  v=fns[s-1](v);
  if(v!==exp.stages[s-1]){console.log("FAIL stage",s,"got",v,"want",exp.stages[s-1]);allok=false;}
}
console.log(allok?"ALL 32 MATCH":"MISMATCH");
'

