const fs = require("fs");
for (let s = 1; s <= 32; s++) {
  const N = s;
  let body;
  if (s % 4 === 1) {
    body = `export function step${s}(v) {\n  return (v + Math.floor(v / 3)) % 997;\n}`;
  } else if (s % 4 === 2) {
    body = `export function step${s}(v) {\n  return v ^ ((${N} * 7) % 64);\n}`;
  } else if (s % 4 === 3) {
    body = `export function step${s}(v) {\n  return (v * 3 - ${N}) % 991;\n}`;
  } else {
    body = `export function step${s}(v) {\n  return (v * 2 + 1) % 1000;\n}`;
  }
  fs.writeFileSync(`src/s${String(s).padStart(2,"0")}.js`, "// 第 " + N + " 级流水线的一段：吃上一级的输出，吐给下一级\n" + body + "\n");
}
console.log("written 32 files");
'
